-- Correct museum records whose prior copy was a disambiguation, wrong-place excerpt,
-- network-level summary, truncated extract or embedded encyclopedia markup.
-- Sources reverified against venue and local-authority pages on 2026-10-14.

UPDATE places SET description_en='The V&A at South Kensington grew from the Museum of Manufactures founded after the Great Exhibition of 1851. Its vast purpose-built complex holds decorative arts and design from many cultures, including ceramics, fashion, furniture, jewellery, metalwork, photography and sculpture. Highlights such as the Cast Courts, Raphael Cartoons and British Galleries make the building itself part of the story of Victorian design education.', description_it='Il V&A di South Kensington nacque dal Museum of Manufactures fondato dopo la Great Exhibition del 1851. Il vasto complesso conserva arti decorative e design di numerose culture: ceramiche, moda, mobili, gioielli, metalli, fotografia e scultura. Spazi come le Cast Courts, i cartoni di Raffaello e le British Galleries rendono l’edificio stesso parte della storia dell’educazione al design nell’età vittoriana.',
  editorial_hook_en='South Kensington’s V&A unites global decorative arts with spectacular Victorian galleries built to teach through design.', editorial_hook_it='Il V&A di South Kensington unisce arti decorative mondiali e spettacolari gallerie vittoriane nate per educare attraverso il design.',
  official_url='https://www.vam.ac.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-4CB4F3CA' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.vam.ac.uk/info/about-us','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-4CB4F3CA'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Whitehall in Cheam is a timber-framed historic house whose earliest fabric dates from about 1500, not the government street in Westminster. Successive occupants enlarged and refitted it, leaving rooms with Tudor structure and Georgian, Victorian and Edwardian details. Displays explore the Killick family, Cheam’s local history and nearby Nonsuch Palace, while the garden preserves a medieval well associated with an earlier building.', description_it='Whitehall a Cheam è una casa storica a graticcio, con le parti più antiche risalenti circa al 1500: non è la strada governativa di Westminster. Gli abitanti successivi la ampliarono e trasformarono, lasciando struttura Tudor e dettagli georgiani, vittoriani ed edoardiani. Le sale raccontano la famiglia Killick, la storia di Cheam e il vicino Nonsuch Palace; nel giardino resta un pozzo medievale legato a un edificio precedente.',
  editorial_hook_en='A timber-framed Cheam house layers five centuries of domestic life, local history and the story of nearby Nonsuch Palace.', editorial_hook_it='Una casa a graticcio di Cheam sovrappone cinque secoli di vita domestica, storia locale e memoria del vicino Nonsuch Palace.',
  official_url='https://libraries.sutton.gov.uk/digital-content/sutton-heritage/whitehall-historic-house', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-733D46DF' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://libraries.sutton.gov.uk/digital-content/sutton-heritage/whitehall-historic-house','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-733D46DF'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Science Gallery London operated at King’s College London’s Guy’s Campus from 2018 until its permanent closure on 1 August 2026. In the restored Boland House opposite London Bridge, its free thematic seasons brought artists, researchers, students and local communities together through exhibitions, performances, experiments and discussions about art, science and health. The gallery programme has ended, although parts of Boland House remain in use.', description_it='Science Gallery London ha operato nel campus Guy’s del King’s College London dal 2018 fino alla chiusura definitiva del 1º agosto 2026. Nella restaurata Boland House, di fronte a London Bridge, le stagioni tematiche gratuite riunivano artisti, ricercatori, studenti e comunità locali con mostre, performance, esperimenti e dibattiti su arte, scienza e salute. Il programma della galleria è terminato, anche se parti di Boland House restano in uso.',
  editorial_hook_en='This former King’s College gallery linked art, science and health in Boland House; its programme closed permanently in August 2026.', editorial_hook_it='Questa ex galleria del King’s College univa arte, scienza e salute a Boland House; il programma ha chiuso definitivamente nell’agosto 2026.',
  official_url='https://london.sciencegallery.com/', access_notes_en='Science Gallery London closed permanently on 1 August 2026. Do not plan a museum visit; consult the official page for information about the continuing uses of Boland House.', access_notes_it='Science Gallery London ha chiuso definitivamente il 1º agosto 2026. Non programmare una visita museale; consulta la pagina ufficiale per gli usi ancora attivi di Boland House.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-F2C58D1E' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://london.sciencegallery.com/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-F2C58D1E'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Burgh House was built in 1704 during Hampstead’s growth as a fashionable spa and has served as a home, officers’ mess and community arts centre. Its panelled Queen Anne rooms now contain Hampstead Museum, whose displays cover local residents, artists and social history. Temporary exhibitions, recitals and talks continue the house’s cultural role, while the walled garden and basement café make its domestic scale easy to appreciate.', description_it='Burgh House fu costruita nel 1704, quando Hampstead cresceva come stazione termale alla moda, ed è stata abitazione, mensa ufficiali e centro artistico comunitario. Le sale rivestite in legno dell’età della regina Anna ospitano oggi Hampstead Museum, dedicato agli abitanti, agli artisti e alla storia sociale del quartiere. Mostre temporanee, concerti e incontri proseguono il ruolo culturale della casa, insieme al giardino e al caffè.',
  editorial_hook_en='A 1704 Queen Anne house combines Hampstead’s local museum with intimate exhibitions, concerts and a secluded garden.', editorial_hook_it='Una casa del 1704 dell’età della regina Anna riunisce il museo di Hampstead, mostre intime, concerti e un giardino appartato.',
  official_url='https://www.burghhouse.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-8BCC3185' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.burghhouse.org.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-8BCC3185'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='London’s Hunterian Museum is inside the Royal College of Surgeons of England in Lincoln’s Inn Fields. At its heart is the collection of eighteenth-century surgeon-anatomist John Hunter, expanded with anatomical and pathological specimens, surgical instruments, models and works of art. The galleries trace the science, craft and ethics of surgery from ancient practice to modern operating theatres, explaining how observation and collecting changed medical knowledge.', description_it='L’Hunterian Museum di Londra si trova nel Royal College of Surgeons of England a Lincoln’s Inn Fields. Il nucleo è la collezione del chirurgo e anatomista settecentesco John Hunter, ampliata con preparati anatomici e patologici, strumenti chirurgici, modelli e opere d’arte. Le gallerie seguono scienza, tecnica ed etica della chirurgia dalle pratiche antiche alle sale operatorie moderne, mostrando come osservazione e collezionismo abbiano trasformato la medicina.',
  editorial_hook_en='John Hunter’s anatomical collection anchors a London museum tracing the art, science and changing ethics of surgery.', editorial_hook_it='La collezione anatomica di John Hunter è il cuore di un museo londinese su arte, scienza ed etica mutevole della chirurgia.',
  official_url='https://hunterianmuseum.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-2EC85679' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://hunterianmuseum.org/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-2EC85679'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Amersham Museum occupies two connected buildings at 49 and 51 High Street in Old Amersham, including a fifteenth-century timber-framed house. Room settings, objects, photographs and oral histories follow the town from medieval market and coaching centre to the arrival of the Metropolitan Railway and twentieth-century growth. A rear garden planted with medicinal and culinary herbs extends the story of domestic life beyond the galleries.', description_it='Amersham Museum occupa due edifici collegati ai numeri 49 e 51 di High Street, a Old Amersham, compresa una casa a graticcio del Quattrocento. Ambienti, oggetti, fotografie e testimonianze orali seguono la città dal mercato medievale e dalle diligenze fino all’arrivo della Metropolitan Railway e alla crescita novecentesca. Sul retro, un giardino di erbe medicinali e culinarie amplia il racconto della vita domestica.',
  editorial_hook_en='A fifteenth-century High Street house connects Old Amersham’s market, coaching and railway histories with everyday local life.', editorial_hook_it='Una casa quattrocentesca sulla High Street collega mercato, diligenze e ferrovia di Old Amersham alla vita quotidiana locale.',
  official_url='https://amershammuseum.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-05AF46FD' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://amershammuseum.org/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-05AF46FD'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='This White Cube pin is the Bermondsey gallery, opened in 2011 in a converted 1970s warehouse on Bermondsey Street. A sequence of large, spare exhibition rooms—including a tall central gallery suited to sculpture and installations—supports ambitious solo shows and historically framed group exhibitions. The building also contains viewing rooms, an auditorium and an archive, making it the gallery’s substantial South London base rather than a reference to its overseas branches.', description_it='Questo punto di White Cube indica la sede di Bermondsey, aperta nel 2011 in un magazzino degli anni Settanta riconvertito su Bermondsey Street. Una sequenza di grandi sale essenziali, compreso uno spazio centrale alto adatto a sculture e installazioni, ospita ambiziose personali e collettive di taglio storico. L’edificio comprende anche viewing rooms, auditorium e archivio: è la grande sede nel sud di Londra, non un riferimento alle filiali estere.',
  editorial_hook_en='White Cube Bermondsey turns a vast former warehouse into monumental rooms for contemporary sculpture, installation and painting.', editorial_hook_it='White Cube Bermondsey trasforma un vasto ex magazzino in sale monumentali per scultura, installazione e pittura contemporanee.',
  official_url='https://www.whitecube.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-048DE124' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.whitecube.com/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-048DE124'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Little Holland House in Carshalton was built between 1902 and 1904 by artist and designer Frank Dickinson as his family home. Inspired by William Morris and the Arts and Crafts movement, Dickinson designed much of the house himself and filled it with hand-painted decoration, carved furniture, metalwork, textiles and pictures. Preserved largely as the family left it, the modest suburban interior shows how Arts and Crafts ideals could shape an entire everyday home.', description_it='Little Holland House a Carshalton fu costruita tra il 1902 e il 1904 dall’artista e designer Frank Dickinson come casa di famiglia. Ispirato da William Morris e dall’Arts and Crafts, Dickinson progettò gran parte dell’edificio e lo riempì di decorazioni dipinte a mano, mobili intagliati, metalli, tessuti e quadri. Conservato in gran parte come lo lasciò la famiglia, l’interno mostra come quegli ideali potessero modellare un’intera casa quotidiana.',
  editorial_hook_en='Frank Dickinson’s hand-built Carshalton home is a remarkably complete, intimate expression of Arts and Crafts ideals.', editorial_hook_it='La casa di Carshalton costruita da Frank Dickinson è un’espressione intima e straordinariamente integra degli ideali Arts and Crafts.',
  official_url='https://libraries.sutton.gov.uk/digital-content/sutton-heritage/little-holland-house', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-26C43108' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://libraries.sutton.gov.uk/digital-content/sutton-heritage/little-holland-house','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-26C43108'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

